1	/**
2	 * Codex CLI 后端 —— spawn `codex` + 把 jsonl 事件归一成统一 Event。
3	 * 移植自 agent-gateway src/backends.ts。模型解析对齐 ClaudeBackend:接入
4	 * endpoints.yaml(@smokingmouse/llm),`--model` 可以是显式标记了 codex 支持的
5	 * 第三方端点的模型名(见 resolveCodexModel)。其余 spawn/解析逻辑保持移植原样。
6	 */
7	import { spawnSync } from "node:child_process";
8	import { randomUUID } from "node:crypto";
9	import * as fs from "node:fs";
10	import * as path from "node:path";
11	import { EventType } from "../events.js";
12	import { streamLines } from "./stream-lines.js";
13	import { loadEndpoints, resolveEndpoint, getApiKey } from "@smokingmouse/llm";
14	// 示意单价(USD / token),真实值由上游配置注入。
15	const CODEX_PRICE = { input: 1.25 / 1_000_000, output: 10.0 / 1_000_000 };
16	/**
17	 * headless fork —— codex exec 没有 fork 子命令(交互版 `codex fork` 有),用等价
18	 * 机制模拟:把父 thread 的 rollout jsonl 复制成新 uuid(文件名 + 全文替换 id),
19	 * 之后 resume 新 id 即是一条继承完整历史、与父线双向隔离的新线(2026-08-04
20	 * codex 0.146.0 实测:历史继承 ✓ 隔离 ✓;resume 需带与录制一致的 -m,否则
21	 * model 漂移告警且曾实测触发上游 400)。
22	 * 找不到父 rollout(id 不存在 / CODEX_HOME 不对 / 父线未持久化)→ throw,由
23	 * run() fail loud —— 静默退化成线性 resume 会让两个"分支"共写同一 thread,
24	 * 上游以为隔离实则互相污染,是错误行为不是降级。
25	 */
26	export function forkCodexSession(parentId, sessionsRoot) {
27	    const root = sessionsRoot ??
28	        path.join(process.env.CODEX_HOME ?? path.join(process.env.HOME ?? "", ".codex"), "sessions");
29	    // rollout 布局 sessions/YYYY/MM/DD/rollout-<ts>-<uuid>.jsonl,按文件名匹配 uuid。
30	    const entries = fs.readdirSync(root, { recursive: true, encoding: "utf8" });
31	    const rel = entries.find((e) => e.includes("rollout-") && e.endsWith(`-${parentId}.jsonl`));
32	    if (!rel) {
33	        throw new Error(`rollout for thread ${parentId} not found under ${root}`);
34	    }
35	    const src = path.join(root, rel);
36	    const newId = randomUUID();
37	    const dst = path.join(path.dirname(src), path.basename(src).replace(parentId, newId));
38	    fs.writeFileSync(dst, fs.readFileSync(src, "utf8").split(parentId).join(newId));
39	    return newId;
40	}
41	/**
42	 * 把 RunOptions.model 解析成 { model, configOverrides?, env? },对齐
43	 * resolveClaudeModel 的三分支语义:
44	 *   ① endpoints.yaml 解析出的端点带 codex.wire_api="responses" 显式标记 →
45	 *      真实 model 名 + `-c model_provider(s)` 注入参数 + api key env。
46	 *   ② 解析出的端点无 codex 标记(chat-only 的 openai_url 等)→ 原样透传,
47	 *      走用户全局 ~/.codex/config.toml —— codex 0.146.0 起 wire_api="chat"
48	 *      已废弃(openai/codex#7782),chat 端点静默注入只会 400,必须 opt-in。
49	 *   ③ 解析失败(codex 原生模型名如 gpt-5.5、CLI 新别名)→ 原样透传给 -m,
50	 *      让 codex CLI 自己校验 —— 不在这一层生降级用户的请求。
51	 * 注入用固定 provider id "sm_endpoint",经 `-c` 与全局 config.toml merge,
52	 * 不落盘不污染用户配置;鉴权走 env_key 指向 endpoints.yaml 的 api_key_env,
53	 * key 值显式放进 spawn env(2026-08-04 codex 0.146.0 正负向实测均通过)。
54	 *
55	 * 2026-08-05 细分失败路径 —— 此前三种"没走注入"全被一个 catch 吞成静默
56	 * 透传,叠加下面的登录闸后,机器间 yaml 未同步 / key 缺失都会伪装成
57	 * 「codex 未登录」(trellis 二号机实锅):
58	 *   degraded:端点在 yaml 里但没标记 codex 支持 → 仍透传(2026-08-04 定的
59	 *     opt-in 语义不变),但把原因带出去,登录闸失败时拼进报错;
60	 *   fatal:端点已标记注入、key 却缺失 → 直接报错。配置自相矛盾时静默换一条
61	 *     鉴权路线,是把配置错误变成别的症状,不是降级。
62	 */
63	function resolveCodexModel(model) {
64	    if (!model)
65	        return { model: undefined };
66	    let endpoint;
67	    try {
68	        ({ endpoint } = resolveEndpoint(loadEndpoints(), model, "openai"));
69	    }
70	    catch {
71	        // 不在 yaml(codex 原生模型名 / 本机没有 yaml)→ 原样透传给 -m,让 codex
72	        // 自己校验 —— 不在这一层生降级用户的请求。
73	        return { model };
74	    }
75	    if (!endpoint.base_url)
76	        return { model: endpoint.model };
77	    if (endpoint.codex?.wire_api !== "responses") {
78	        return {
79	            model,
80	            degraded: `模型「${model}」命中的 endpoints.yaml 端点未标记 codex 支持` +
81	                `(codex: { wire_api: responses }),本次按原生模式透传 —— ` +
82	                `若该端点在别的机器上标记过,多半是这台机器的 yaml 没同步`,
83	        };
84	    }
85	    let key;
86	    try {
87	        key = getApiKey(endpoint);
88	    }
89	    catch (e) {
90	        return {
91	            model,
92	            fatal: `模型「${model}」的端点已标记 codex 注入,但 key 缺失:` +
93	                `${e instanceof Error ? e.message : String(e)}` +
94	                `(本机 ~/.agent-gateway.env 或 endpoints.yaml 的 env_file 未配这台机器的 key)`,
95	        };
96	    }
97	    const p = "model_providers.sm_endpoint";
98	    return {
99	        model: endpoint.model,
100	        configOverrides: [
101	            "-c", `model_provider="sm_endpoint"`,
102	            "-c", `${p}.name="sm-endpoint"`,
103	            "-c", `${p}.base_url="${endpoint.base_url}"`,
104	            "-c", `${p}.env_key="${endpoint.api_key_env}"`,
105	            "-c", `${p}.wire_api="${endpoint.codex.wire_api}"`,
106	        ],
107	        env: { [endpoint.api_key_env]: key },
108	    };
109	}
110	export class CodexBackend {
111	    name = "codex";
112	    capabilities() {
113	        return {
114	            workspace: true,
115	            tools: true,
116	            mcp: true,
117	            sandboxModes: ["read-only", "workspace-write", "full-access"],
118	            permissionPolicies: ["readonly", "auto-edit", "full"],
119	            readonlyEnforcement: "os-sandbox", // OS 级只读,Bash 也无法绕过
120	            dynamicPermissionCallback: false, // Phase 2:需 app-server JSON-RPC
121	            vision: true, // --image FILE
122	            toolAllowlist: false, // codex 无工具白名单(sandbox 决定可达)
123	            streaming: "block", // codex --json 不发 per-token,agent_message 整段出
124	            costInStream: false, // 只给 token,$ 需上游按单价估
125	            structuredOutput: true, // --output-schema
126	            reportsCapabilityAtRuntime: false, // thread.started 不含 tools/model
127	            resume: true,
128	            // headless fork:exec 无原生 fork 子命令,由 rollout copy 模拟(forkCodexSession)。
129	            forkSession: true,
130	            // model 可解析 endpoints.yaml,切显式标记的第三方 Responses 端点(-c 注入);
131	            // 约束:codex ≥0.146 只认 wire_api="responses",chat-only 端点不可用。
132	            configDrivenModelSwitch: true,
133	        };
134	    }
135	    async *run(prompt, opts) {
136	        const resolved = resolveCodexModel(opts.model);
137	        // 配置矛盾(端点标记了注入但 key 缺失)→ 报真实原因,不 spawn。
138	        if (resolved.fatal) {
139	            yield ev(this.name, EventType.Error, null, { message: resolved.fatal });
140	            return;
141	        }
142	        // 登录检查(便宜 ~50ms):给清晰可操作错误,避免浪费一次必 401 的往返。
143	        // 注入端点时跳过 —— 鉴权走 env_key(API key),不依赖 ChatGPT 登录态。
144	        if (!resolved.configOverrides) {
145	            const login = spawnSync("codex", ["login", "status"], { encoding: "utf8", timeout: 5000 });
146	            if (login.status !== 0) {
147	                // 报错必须把解析降级的原因带上:透传模式走的是 ChatGPT 登录态,而用户
148	                // 以为自己选了第三方端点 —— 只喊「未登录」会把配置漂移伪装成登录问题。
149	                const hint = resolved.degraded ??
150	                    "若期望走第三方端点(不依赖 ChatGPT 登录),对应 endpoints.yaml 端点需带 codex: { wire_api: responses } 标记,且本机配有它的 key。";
151	                yield ev(this.name, EventType.Error, null, {
152	                    message: `codex 未登录(ChatGPT)。原生模式需先在终端运行 \`codex login\`。\n${hint}`,
153	                });
154	                return;
155	            }
156	        }
157	        // caller 显式传的 env 优先级高于按 model 解析出的 env(对齐 ClaudeBackend)。
158	        const spawnEnv = resolved.env || opts.env ? { ...resolved.env, ...opts.env } : undefined;
159	        // fork 续会话:headless 模拟 claude --fork-session(rollout copy,见 forkCodexSession)。
160	        // 失败必须 fail loud,绝不静默线性 resume(那会让树形分支互相污染)。
161	        let resumeId = opts.resume ?? null;
162	        if (resumeId && opts.forkSession) {
163	            try {
164	                resumeId = forkCodexSession(resumeId);
165	            }
166	            catch (e) {
167	                yield ev(this.name, EventType.Error, null, {
168	                    message: `codex fork 失败(线程 ${resumeId}):${e instanceof Error ? e.message : String(e)}`,
169	                });
170	                return;
171	            }
172	        }
173	        // codex 无 --system-prompt,把它 inline 到 prompt 前(read-only sandbox 时主要影响风格)。
174	        const finalPrompt = opts.systemPrompt ? `${opts.systemPrompt}\n\n---\n\n${prompt}` : prompt;
175	        const policy = opts.permission ?? (opts.workspace ? "auto-edit" : "readonly");
176	        const args = buildCodexArgs({
177	            policy,
178	            ephemeral: opts.persistence === false,
179	            model: resolved.model,
180	            configOverrides: resolved.configOverrides,
181	            resume: resumeId,
182	            additionalWritableDirs: opts.additionalWritableDirs ?? [],
183	            sandboxNetworkAccess: opts.sandboxNetworkAccess === true,
184	            imagePaths: (opts.attachments ?? []).map((a) => a.path),
185	            prompt: finalPrompt,
186	            additionalDirs: opts.additionalWorkspaces ?? [],
187	            environmentSkills: opts.environmentSkills,
188	            environmentSkillNames: opts.environmentSkillNames,
189	        });
190	        let sid = resumeId;
191	        const finalText = [];
192	        // 按 item id 记已转发长度,防 item.updated/completed 对同一条重复 emit。
193	        const emittedLen = new Map();
194	        // 已发过 ToolCall 的 item id(item.started 先到;某些 build 只发 completed,
195	        // 届时在 completed 补发 start 再发 done,保证上游永远能按 id 配对)。
196	        const startedTools = new Set();
197	        let anonToolSeq = 0;
198	        // stderr 兜底(对齐 ClaudeBackend):CLI 报错而事件流无信息量时拼 stderr 尾部,
199	        // 避免只剩 generic "codex error"。
200	        const stderrSink = { text: "" };
201	        for await (const raw of streamLines("codex", args, {
202	            cwd: opts.cwd ?? opts.workspace ?? undefined,
203	            env: spawnEnv,
204	            signal: opts.signal,
205	            stderrSink,
206	        })) {
207	            let obj;
208	            try {
209	                obj = JSON.parse(raw);
210	            }
211	            catch {
212	                continue;
213	            }
214	            const t = obj.type;
215	            if (t === "thread.started") {
216	                sid = obj.thread_id ?? sid;
217	                yield ev(this.name, EventType.SessionStart, sid, {
218	                    tools: null,
219	                    // thread.started 不自报 model;注入端点时后端确知实际命中的 model,
220	                    // 回填之。透传场景仍 null(全局 config.toml 可能改写,不冒充事实)。
221	                    model: resolved.configOverrides ? (resolved.model ?? null) : null,
222	                    note: "capability from static declaration",
223	                });
224	            }
225	            else if ((t === "item.updated" || t === "item.completed") && obj.item?.type === "agent_message") {
226	                // codex agent_message 整段(无 per-token);newer build 可能 item.updated 增量,按 id dedup。
227	                const id = obj.item.id ?? "default";
228	                const text = obj.item.text ?? "";
229	                const prev = emittedLen.get(id) ?? 0;
230	                if (text.length > prev) {
231	                    const delta = text.slice(prev);
232	                    finalText.push(delta);
233	                    yield ev(this.name, EventType.TextChunk, sid, { text: delta });
234	                    emittedLen.set(id, text.length);
235	                }
236	            }
237	            else if ((t === "item.updated" || t === "item.completed") && obj.item?.type === "reasoning") {
238	                // reasoning item = codex 的思考摘要。不发的话高 effort 下上游整个思考期
239	                // 零反馈(与 claude Thinking 同一个失明问题)。按 id 长度 diff 去重。
240	                const id = obj.item.id ?? "reasoning";
241	                const text = obj.item.text ?? "";
242	                const prev = emittedLen.get(id) ?? 0;
243	                if (text.length > prev) {
244	                    yield ev(this.name, EventType.Thinking, sid, { text: text.slice(prev) });
245	                    emittedLen.set(id, text.length);
246	                }
247	            }
248	            else if (isToolItem(obj.item?.type) && (t === "item.started" || t === "item.completed")) {
249	                // 工具生命周期:started 发 ToolCall(带 id 供配对),completed 发 ToolCallDone
250	                // (带输出/错误)。此前只在 completed 发一条无 id 的 ToolCall——上游按 id
251	                // 去重会把整轮工具吞到只剩一条,且永远 running。
252	                const item = obj.item;
253	                const id = item.id ?? `codex-tool-${anonToolSeq++}`;
254	                const call = toolCallFields(item);
255	                if (!startedTools.has(id)) {
256	                    startedTools.add(id);
257	                    yield ev(this.name, EventType.ToolCall, sid, { id, ...call, parentToolUseId: null });
258	                }
259	                if (t === "item.completed") {
260	                    yield ev(this.name, EventType.ToolCallDone, sid, {
261	                        id,
262	                        output: toolOutput(item),
263	                        stderr: null, // codex aggregated_output 不拆 stdout/stderr
264	                        isError: item.status === "failed" ||
265	                            (typeof item.exit_code === "number" && item.exit_code !== 0),
266	                    });
267	                }
268	            }
269	            else if (t === "item.completed" && obj.item?.type === "file_change") {
270	                yield ev(this.name, EventType.FileChange, sid, { changes: obj.item.changes });
271	            }
272	            else if (t === "turn.completed") {
273	                const u = obj.usage ?? {};
274	                const totalIn = u.input_tokens ?? 0, cached = u.cached_input_tokens ?? 0;
275	                const netIn = Math.max(0, totalIn - cached); // 对齐 Anthropic 语义:input 不含 cache 命中
276	                const cost = {
277	                    usd: Number((netIn * CODEX_PRICE.input + (u.output_tokens ?? 0) * CODEX_PRICE.output).toFixed(6)),
278	                    inputTokens: netIn,
279	                    outputTokens: u.output_tokens ?? 0,
280	                    cachedTokens: cached,
281	                    cacheCreation: 0, // codex 不报
282	                    estimated: true,
283	                    // codex 是单轮 block(无 claude 那种跨迭代累计),整轮输入即当前占用。
284	                    contextTokens: totalIn,
285	                };
286	                yield ev(this.name, EventType.Result, sid, { text: finalText.join(""), cost });
287	                return;
288	            }
289	            else if (t === "turn.failed") {
290	                const stderrTail = stderrSink.text.trim();
291	                const message = obj.error?.message || (stderrTail ? stderrTail.slice(-500) : null) || "codex turn failed";
292	                yield ev(this.name, EventType.Error, sid, { message });
293	                return;
294	            }
295	            else if (t === "error") {
